568	// addLink adds a link if it passes validation to ensure it will not contribute to
569	// ValidateLinks errors. It also attempts to convert a link with URL scheme "" to
570	// "mailto" and avoids duplicate links.
571	func addLink(links map[string][]string, key, link string) {
572		if key == "" || !isValidLinksKey(key) {
573			return
574		}
575		if link == "" {
576			return
577		}
578		u, err := url.Parse(link)
579		if err != nil {
580			return
581		}
582		if u.Scheme == "" {
583			link = "mailto:" + link
584			u.Scheme = "mailto"
585		}
586		if u.Scheme == "mailto" {
587			// minimal check
588			if !strings.Contains(link, "@") {
589				return
590			}
591		} else if !strutil.ListContains(validLinkSchemes, u.Scheme) {
592			return
593		}
594		if strutil.ListContains(links[key], link) {
595			return
596		}
597		links[key] = append(links[key], link)
598	}
